// Worker entry: serves the Next.js app (OpenNext), its static files, and runs Cron Triggers.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
// @ts-expect-error: generated by scripts/embed-assets.mjs
import EMBEDDED from "./.open-next/embedded-assets.mjs";

type Asset = { body: string | ArrayBuffer; type: string };
const ASSETS_MAP = EMBEDDED as Record<string, Asset>;

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

/** Static files are embedded in the bundle (see scripts/embed-assets.mjs). */
function serveAsset(pathname: string, method: string): Response | null {
  let path = decodeURIComponent(pathname);
  if (path.endsWith("/")) path += "index.html";
  const a = ASSETS_MAP[path];
  if (!a) return null;
  const immutable = path.startsWith("/_next/static/");
  return new Response(method === "HEAD" ? null : a.body, {
    headers: {
      "Content-Type": a.type,
      "Cache-Control": immutable ? "public, max-age=31536000, immutable" : "public, max-age=0, must-revalidate",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

// Stand-in for the Workers Static Assets binding that OpenNext expects.
const assetsBinding = {
  async fetch(input: RequestInfo | URL): Promise<Response> {
    const url = new URL(input instanceof Request ? input.url : String(input));
    return serveAsset(url.pathname, "GET") ?? new Response("Not found", { status: 404 });
  },
};

const CRON_ROUTES: Record<string, string> = {
  "*/5 * * * *": "/api/cron/meetings",
  "*/15 * * * *": "/api/cron/emails",
};

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    if (request.method === "GET" || request.method === "HEAD") {
      const asset = serveAsset(new URL(request.url).pathname, request.method);
      if (asset) return asset;
    }
    return handler.fetch(request, { ...env, ASSETS: assetsBinding }, ctx);
  },

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const path = CRON_ROUTES[controller.cron];
    if (!path || !env.CRON_SECRET) {
      console.warn(`[cron] skipped "${controller.cron}" (no route or CRON_SECRET)`);
      return;
    }
    // Run the same authenticated API route an external scheduler would call.
    const req = new Request(`https://jarvis.internal${path}`, {
      headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const res: Response = await handler.fetch(req, { ...env, ASSETS: assetsBinding }, ctx);
    console.log(`[cron] ${path} → ${res.status} ${(await res.text()).slice(0, 300)}`);
  },
} satisfies ExportedHandler<Env>;
